#include "../include/cli.h"

CLI::CLI(commandType *commands, int numCommands) {
    _commands = commands;
    _numCommands = numCommands;
    _inputBufferIndex = 0;
}

void CLI::loop() {
    while (Serial.available()) {
        char c = Serial.read();
        if (c == '\n' || c == '\r') {
            Serial.println();
            if (_inputBufferIndex > 0) {
                _inputBuffer[_inputBufferIndex] = '\0';
                parseInput(_inputBuffer);
                _inputBufferIndex = 0;
            }
            while (Serial.available()) {
                int p = Serial.peek();
                if (p == '\n' || p == '\r') {
                    Serial.read();
                } else {
                    break;
                }
            }
            Serial.print(F("ArduinoOS > "));
        }
        else if (_inputBufferIndex < INPUT_BUF_SIZE - 1) {
            _inputBuffer[_inputBufferIndex++] = c;
            Serial.write(c);
        }
    }
}

void CLI::parseInput(char *input) {
    char *args = nullptr;
    char *space = strchr(input, ' ');
    if (space != nullptr) {
        *space = '\0';
        args = space + 1;
        if (*args == '\0') {
            args = nullptr;
        }
    }
    for (int i = 0; i < _numCommands; i++) {
        if (strcmp(_commands[i].name, input) == 0) {
            _commands[i].func(args);
            return;
        }
    }
    Serial.println(F("Unknown command"));
}

#include "../include/cli.h"

CLI::CLI(commandType *commands, int numCommands) {
    _commands = commands;
    _numCommands = numCommands;
    _inputBufferIndex = 0;
}

void CLI::loop() {
    while (Serial.available()) {
        char c = Serial.read();
        if (c == '\n' || c == '\r') {
            Serial.println();
            if (_inputBufferIndex > 0) {
                _inputBuffer[_inputBufferIndex] = '\0';
                parseInput(_inputBuffer);
                _inputBufferIndex = 0;
            }
            while (Serial.available()) {
                int p = Serial.peek();
                if (p == '\n' || p == '\r') {
                    Serial.read();
                } else {
                    break;
                }
            }
            Serial.print(F("ArduinoOS > "));
        }
        else if (_inputBufferIndex < INPUT_BUF_SIZE - 1) {
            _inputBuffer[_inputBufferIndex++] = c;
            Serial.write(c);
        }
    }
}

void CLI::parseInput(char *input) {
    char *args = nullptr;
    char *space = strchr(input, ' ');
    if (space != nullptr) {
        *space = '\0';
        args = space + 1;
        if (*args == '\0') {
            args = nullptr;
        }
    }
    for (int i = 0; i < _numCommands; i++) {
        const char* progmemName = (const char*) pgm_read_ptr(&_commands[i].name);
        if (strcmp_P(input, progmemName) == 0) {
            _commands[i].func(args);
            return;
        }
    }
    Serial.println(F("Unknown command"));
}

#include "../include/commands.h"
#include "../include/FAT.h"

void helpCommand(char *args) {
    if (args == nullptr) {
        for (int i = 0; i < numCommands; i++) {
            Serial.print(commands[i].name);
            Serial.print(" - ");
            Serial.println(commands[i].description);
        }
    } else {
        for (int i = 0; i < numCommands; i++) {
            if (strcmp(commands[i].name, args) == 0) {
                Serial.print(commands[i].name);
                Serial.print(" - ");
                Serial.println(commands[i].description);
                return;
            }
        }
    }
}

void printCommand(char *args) {
    if (args != nullptr) {
        Serial.println(args);
    } else {
        Serial.println("print: No arguments provided");
    }
}


void filesCommand(char *args) {
    if (noOfFiles == 0) {
        Serial.println("No files in the filesystem");
    } else {
        printFileList();
    }
}

void freeSpaceCommand(char *args) {
    int freeSpace = getFreeSpace();
    Serial.print("Free space: ");
    Serial.print(freeSpace);
    Serial.println(" bytes");
}

